head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.COLS = ["col1", "col2", "col3", "col4"];

// 초기 4행(전 행 상태 R) 으로 되돌린다
scwin.resetData = function () {
    var arrInit = [];
    for (var i = 1; i <= 4; i++) {
        arrInit.push({ col1: "col1_" + i, col2: "col2_" + i, col3: "col3_" + i, col4: "col4_" + i });
    }
    $p.getComponentById("dlt_target").setJSON(arrInit);
};

// 행별 col1~col4 값과 getRowStatus() 를 한 줄씩 출력
scwin.printRows = function (strPrefix) {
    var objDlt = $p.getComponentById("dlt_target");
    var nCnt = objDlt.getRowCount();
    scwin.setReturnValue(strPrefix + " rowCount : " + nCnt);
    for (var i = 0; i < nCnt; i++) {
        var arrVal = [];
        for (var j = 0; j < scwin.COLS.length; j++) {
            var strVal = objDlt.getCellData(i, scwin.COLS[j]);
            arrVal.push((strVal === "" || strVal === null || strVal === undefined) ? "(빈값)" : strVal);
        }
        scwin.setReturnValue("  row " + i + " : " + arrVal.join(" / ") + "   status : " + objDlt.getRowStatus(i));
    }
};

scwin.btn_setRowArray_onclick = function (e) {
    scwin.resetData();
    scwin.printRows("[setRowArray(-1)] 호출 전");

    var rowData = {};
    rowData.columnInfo = ["col1", "col2", "col3", "col4"];
    rowData.data = ["setcol1", "setcol2", "setcol3", "setcol4"];
    $p.getComponentById("dlt_target").setRowArray(-1, rowData);

    scwin.printRows("[setRowArray(-1)] 호출 후");
    scwin.setReturnValue("");
};

scwin.btn_setRowData_onclick = function (e) {
    scwin.resetData();
    scwin.printRows("[setRowData(-1)] 호출 전");

    $p.getComponentById("dlt_target").setRowData(-1, ["setcol1", "setcol2", "setcol3", "setcol4"]);

    scwin.printRows("[setRowData(-1)] 호출 후");
    scwin.setReturnValue("");
};

scwin.btn_setRowJSON_onclick = function (e) {
    scwin.resetData();
    scwin.printRows("[setRowJSON(-1)] 호출 전");

    var rowData = { col1: "setcol1", col2: "setcol2", col3: "setcol3", col4: "setcol4" };
    $p.getComponentById("dlt_target").setRowJSON(-1, rowData, false);

    scwin.printRows("[setRowJSON(-1)] 호출 후");
    scwin.setReturnValue("");
};
